/**
 * OpenCode Hook Event Types (Anthropic-compatible)
 * Based on OpenCode's Anthropic hooks implementation
 * https://github.com/principle-md/opencode/blob/feature/comprehensive-hooks-integration/HOOKS_INTEGRATION.md
 */

/**
 * Common fields present in all OpenCode hook events (Anthropic format)
 */
export interface OpenCodeHookCommon {
  session_id: string;
  transcript_path: string;
  cwd: string;
  hook_event_name: string;
}

/**
 * PreToolUse event - before tool execution
 */
export interface OpenCodePreToolUseEvent extends OpenCodeHookCommon {
  hook_event_name: 'PreToolUse';
  tool_name: string;
  tool_input: unknown; // Structure depends on the tool
}

/**
 * PostToolUse event - after tool execution
 */
export interface OpenCodePostToolUseEvent extends OpenCodeHookCommon {
  hook_event_name: 'PostToolUse';
  tool_name: string;
  tool_input: unknown;
  tool_response: unknown; // Structure depends on the tool
}

/**
 * Notification event
 */
export interface OpenCodeNotificationEvent extends OpenCodeHookCommon {
  hook_event_name: 'Notification';
  message: string;
}

/**
 * UserPromptSubmit event - when user submits a prompt
 */
export interface OpenCodeUserPromptSubmitEvent extends OpenCodeHookCommon {
  hook_event_name: 'UserPromptSubmit';
  prompt: string;
}

/**
 * Stop event - when OpenCode finishes responding
 */
export interface OpenCodeStopEvent extends OpenCodeHookCommon {
  hook_event_name: 'Stop';
  stop_hook_active?: boolean;
}

/**
 * SubagentStop event - when a subagent (Task tool) finishes
 */
export interface OpenCodeSubagentStopEvent extends OpenCodeHookCommon {
  hook_event_name: 'SubagentStop';
  stop_hook_active?: boolean;
}

/**
 * PreCompact event - before context compaction
 */
export interface OpenCodePreCompactEvent extends OpenCodeHookCommon {
  hook_event_name: 'PreCompact';
  trigger: 'manual' | 'auto';
  custom_instructions?: string;
}

/**
 * SessionStart event - when session starts or resumes
 */
export interface OpenCodeSessionStartEvent extends OpenCodeHookCommon {
  hook_event_name: 'SessionStart';
  source: 'startup' | 'resume' | 'clear';
}

/**
 * Union type of all OpenCode hook events (Anthropic format)
 */
export type OpenCodeHookEvent =
  | OpenCodePreToolUseEvent
  | OpenCodePostToolUseEvent
  | OpenCodeNotificationEvent
  | OpenCodeUserPromptSubmitEvent
  | OpenCodeStopEvent
  | OpenCodeSubagentStopEvent
  | OpenCodePreCompactEvent
  | OpenCodeSessionStartEvent;

/**
 * Type guards for OpenCode events
 */
export function isOpenCodePreToolUse(data: unknown): data is OpenCodePreToolUseEvent {
  return isOpenCodeEvent(data) && data.hook_event_name === 'PreToolUse';
}

export function isOpenCodePostToolUse(data: unknown): data is OpenCodePostToolUseEvent {
  return isOpenCodeEvent(data) && data.hook_event_name === 'PostToolUse';
}

export function isOpenCodeNotification(data: unknown): data is OpenCodeNotificationEvent {
  return isOpenCodeEvent(data) && data.hook_event_name === 'Notification';
}

export function isOpenCodeUserPromptSubmit(data: unknown): data is OpenCodeUserPromptSubmitEvent {
  return isOpenCodeEvent(data) && data.hook_event_name === 'UserPromptSubmit';
}

export function isOpenCodeStop(data: unknown): data is OpenCodeStopEvent {
  return isOpenCodeEvent(data) && data.hook_event_name === 'Stop';
}

export function isOpenCodeSubagentStop(data: unknown): data is OpenCodeSubagentStopEvent {
  return isOpenCodeEvent(data) && data.hook_event_name === 'SubagentStop';
}

export function isOpenCodePreCompact(data: unknown): data is OpenCodePreCompactEvent {
  return isOpenCodeEvent(data) && data.hook_event_name === 'PreCompact';
}

export function isOpenCodeSessionStart(data: unknown): data is OpenCodeSessionStartEvent {
  return isOpenCodeEvent(data) && data.hook_event_name === 'SessionStart';
}

/**
 * Base type guard for OpenCode events
 */
export function isOpenCodeEvent(data: unknown): data is OpenCodeHookEvent {
  return (
    typeof data === 'object' &&
    data !== null &&
    'session_id' in data &&
    'transcript_path' in data &&
    'cwd' in data &&
    'hook_event_name' in data
  );
}

/**
 * Known OpenCode tool names (from Anthropic-compatible implementation)
 * Based on the documentation's tool list
 */
export const OPENCODE_TOOLS = {
  // File operations
  READ: 'Read',
  WRITE: 'Write',
  EDIT: 'Edit',
  MULTI_EDIT: 'MultiEdit',

  // Search operations
  BASH: 'Bash',
  GLOB: 'Glob',
  GREP: 'Grep',
  LS: 'LS',

  // Web operations
  WEB_FETCH: 'WebFetch',
  WEB_SEARCH: 'WebSearch',

  // Task management
  TASK: 'Task',
  TODO_WRITE: 'TodoWrite',

  // Notebook operations
  NOTEBOOK_READ: 'NotebookRead',
  NOTEBOOK_EDIT: 'NotebookEdit',

  // Other
  EXIT_PLAN_MODE: 'ExitPlanMode',
} as const;

export type OpenCodeToolName = (typeof OPENCODE_TOOLS)[keyof typeof OPENCODE_TOOLS] | string;
